// The face library's built-in data: two signed-distance fonts and the toy art. The data file is generated by
// art/face/tools/build_face_assets.py.
#pragma once

#include <stdint.h>

namespace face {

// A glyph cell of the distance table: w x h bytes at `off`, 128 = on the edge, higher = inside. (x0, y0) is the
// cell's top-left relative to the pen on the baseline, in em px (y down).
struct Glyph {
  uint16_t cp;
  uint8_t w, h;
  int8_t x0, y0;
  float adv;
  uint32_t off;
};
struct Kern {
  uint16_t a, b;
  float dx;
};
struct Font {
  float em;      // px per em the table was made at
  float spread;  // em px of distance either side of the edge that 0..255 covers
  const Glyph* glyphs;
  int count;
  const uint8_t* sdf;
  const Kern* kern;
  int kernCount;
};
extern const Font FONT_SHOUT;  // Bagel Fat One
extern const Font FONT_SAY;    // Lilita One

// Straight-alpha RGBA.
struct Bitmap {
  int w, h;
  const uint8_t* rgba;
};
extern const Bitmap IMAGES[];
extern const char* const IMAGE_NAMES[];
extern const int IMAGE_COUNT;

// Indices into IMAGES, in build order.
enum Img : uint8_t {
  IMG_CHEETAH, IMG_HONEYBEE, IMG_HUMMINGBIRD, IMG_SPIDER, IMG_OWL, IMG_DOLPHIN, IMG_BAT, IMG_CHAMELEON, IMG_EGG,
  IMG_CAKE, IMG_TREAT, IMG_FLOWER, IMG_GOLFFLAG, IMG_WHIRLIGIG, IMG_SOUND, IMG_REMOTE
};

}  // namespace face
